//! Automatic, mod-first style references, the style statistics and the `style` check, through the engine.
//!
//! SYNTHETIC: every image here is generated by the test. No Paradox art is involved, and provider replies come from
//! the fixture transport. The last test runs against the real game and the real Chaos Redux checkout when they exist.

mod common;

use std::path::{Path, PathBuf};
use std::sync::Arc;

use common::{openai_harness, repo_work_dir, synthetic_icon_png, temp_project, Harness};
use imagegen_core::config::MapEnv;
use imagegen_core::dds;
use imagegen_core::hashing::FixedClock;
use imagegen_core::pixels::{encode_png, Rgba};
use imagegen_core::refs::RefOrigin;
use imagegen_mcp::{Engine, RunMode};
use imagegen_providers::transport::FixtureTransport;
use serde_json::{json, Value};

const KEY: (&str, &str) = ("OPENAI_API_KEY", "sk-test-synthetic-000");

/// An idea-spirit-sized (60x68) icon: a filled rounded block with a little texture. `i` varies size and detail.
fn spirit_icon(rgb: [u8; 3], outline: bool, i: u32) -> Rgba {
    let mut img = Rgba::new(60, 68);
    let inset = 4 + (i % 4);
    for y in inset..68 - inset {
        for x in inset..60 - inset {
            let rim = x == inset || y == inset || x == 59 - inset || y == 67 - inset;
            let tex = ((x * 3 + y * 5 + i * 11) % 9) as i32 - 4;
            let c = |v: u8| (i32::from(v) + tex * 2).clamp(0, 255) as u8;
            let px = if rim && outline { [12, 12, 12, 255] } else { [c(rgb[0]), c(rgb[1]), c(rgb[2]), 255] };
            img.set_px(x, y, px);
        }
    }
    img
}

fn write_png(root: &Path, rel: &str, img: &Rgba) {
    let path = root.join(rel);
    std::fs::create_dir_all(path.parent().unwrap()).unwrap();
    std::fs::write(path, encode_png(img).unwrap()).unwrap();
}

/// `n` mod icons of idea_spirit under `gfx/interface/ideas/<feature>/`.
fn mod_spirits(root: &Path, feature: &str, n: u32, rgb: [u8; 3], outline: bool) {
    for i in 0..n {
        let shade = if rgb[0] == rgb[1] && rgb[1] == rgb[2] {
            [rgb[0].saturating_add((i * 2) as u8); 3]
        } else {
            [rgb[0].saturating_add((i * 3) as u8), rgb[1].saturating_add((i * 2) as u8), rgb[2].saturating_add(i as u8)]
        };
        write_png(root, &format!("gfx/interface/ideas/{feature}/idea_{i:02}.png"), &spirit_icon(shade, outline, i));
    }
}

fn plan_spirit(h: &Harness) -> imagegen_core::plan::Plan {
    h.engine
        .plan(
            serde_json::from_value(json!({
                "family": "idea_spirit", "feature_slug": "f", "asset": "iron_will", "brief": "an iron will", "provider": "openai", "quality": "low"
            }))
            .unwrap(),
        )
        .unwrap()
}

fn sources(plan: &imagegen_core::plan::Plan) -> Value {
    serde_json::to_value(plan.style_sources.as_ref().expect("a plan always reports its style sources")).unwrap()
}

/// A harness whose game folder is `game`.
fn harness_with_game(game: &Path) -> Harness {
    let dir = temp_project("[defaults]\nprovider = \"openai\"\n");
    let fixture = Arc::new(FixtureTransport::new());
    let auth = dir.path().join("chatgpt-auth.json").display().to_string();
    let game_s = game.display().to_string();
    let env = MapEnv::from_pairs(&[KEY, ("HOI4_GAME_DIR", &game_s), ("HOI4_IMAGEGEN_CHATGPT_AUTH", &auth)]);
    let engine = Engine::open(dir.path(), Arc::new(env), fixture.clone(), Arc::new(FixedClock(1_793_404_800)), RunMode::Cli).unwrap();
    Harness { dir, engine, fixture }
}

/// A fake installed game with `n` vanilla-sized idea_spirit textures (DDS) made by the test.
fn fake_game(n: u32) -> tempfile::TempDir {
    let game = tempfile::Builder::new().prefix("g").tempdir_in(repo_work_dir()).unwrap();
    std::fs::create_dir_all(game.path().join("interface")).unwrap();
    let ideas = game.path().join("gfx/interface/ideas");
    std::fs::create_dir_all(&ideas).unwrap();
    for i in 0..n {
        let img = spirit_icon([90 + (i * 7) as u8, 110, 140 - (i * 5) as u8], i % 2 == 0, i);
        std::fs::write(ideas.join(format!("idea_fake_{i:02}.dds")), dds::write_a8r8g8b8(&img)).unwrap();
    }
    // a decoy of another family's size in the same folder must not be picked
    std::fs::write(ideas.join("idea_decoy.dds"), dds::write_a8r8g8b8(&Rgba::filled(65, 67, [255, 0, 0, 255]))).unwrap();
    game
}

fn chosen(report: &Value) -> Vec<Value> {
    report["chosen"].as_array().unwrap().clone()
}

fn sent(report: &Value) -> Vec<Value> {
    chosen(report).into_iter().filter(|c| c["sent_to_provider"] == true).collect()
}

#[test]
fn a_mod_with_its_own_icons_uses_them_before_vanilla() {
    let game = fake_game(8);
    let h = harness_with_game(game.path());
    mod_spirits(h.root(), "my_feature", 12, [120, 120, 120], true);
    let plan = plan_spirit(&h);
    let r = sources(&plan);
    assert_eq!(r["chosen_tier"], 3, "{r:#}");
    let tiers = r["tiers"].as_array().unwrap();
    assert_eq!(tiers[2]["found"], 12);
    assert_eq!(tiers[2]["chosen"], true);
    assert_eq!(tiers[3]["scanned"], false, "vanilla is not even scanned when the mod has enough: {r:#}");
    let s = sent(&r);
    assert!((1..=4).contains(&s.len()), "{s:?}");
    for c in &s {
        assert_eq!(c["tier"], 3);
        assert!(c["path"].as_str().unwrap().starts_with("gfx/interface/ideas/my_feature/"), "{c}");
        assert!(c["reason"].as_str().unwrap().starts_with("mod asset: medoid "), "{c}");
        assert!(c["reason"].as_str().unwrap().contains("of 12 idea_spirit images"), "{c}");
        assert_eq!(c["sha256"].as_str().unwrap().len(), 64);
    }
    assert!(plan.references.iter().all(|x| x.origin == RefOrigin::Project));
    assert_eq!(plan.references.len(), s.len());
    // the clean PNG hash is what the plan records
    for (c, rs) in s.iter().zip(&plan.references) {
        assert_eq!(c["sha256"], json!(rs.sha256));
    }
    // statistics-only entries are listed and marked as never sent
    let stats_only: Vec<Value> = chosen(&r).into_iter().filter(|c| c["sent_to_provider"] == false).collect();
    assert!(stats_only.iter().all(|c| c["used_for_statistics"] == true && c["reason"].as_str().unwrap().contains("never sent")));
    // the prompt carries the measured paragraph
    assert!(plan.prompt.text.contains("Match the mod's existing idea and national spirit picture art"), "{}", plan.prompt.text);
    // the family tool reports the same picture
    let info = h.engine.families_info(serde_json::from_value(json!({"family": "idea_spirit"})).unwrap()).unwrap();
    let a = &info["family"]["style_sources"]["automatic"];
    assert_eq!(a["chosen_tier"], 3);
    assert_eq!(a["tiers"][3]["scanned"], true, "families looks at every tier");
    assert_eq!(a["tiers"][3]["found"], 8, "the 65x67 decoy is not an idea_spirit size");
    assert!(a["statistics"]["images"].as_u64().unwrap() >= 3);
    assert!(a["drift"]["threshold"].as_f64().unwrap() >= 1.75);
}

#[test]
fn a_pinned_style_wins_over_everything_else() {
    let game = fake_game(8);
    let h = harness_with_game(game.path());
    mod_spirits(h.root(), "my_feature", 12, [120, 120, 120], true);
    // three pinned references of a different look (reds)
    let mut refs = Vec::new();
    for i in 0..3 {
        let rel = format!("references/idea_spirit/pinned_{i}.png");
        write_png(h.root(), &rel, &spirit_icon([200 - i as u8 * 10, 30, 30], false, i));
        refs.push(json!({"path": rel, "sha256": "", "note": "synthetic test image"}));
    }
    h.engine
        .references(
            serde_json::from_value(json!({"action": "style_save", "style": {"name": "mine", "families": ["idea_spirit"], "references": refs,
                "description": "Painted gouache."}}))
            .unwrap(),
        )
        .unwrap();
    let plan = plan_spirit(&h);
    let r = sources(&plan);
    assert_eq!(r["chosen_tier"], 1, "{r:#}");
    let s = sent(&r);
    assert_eq!(s.len(), 3, "three pinned references are all sent: {s:?}");
    assert!(s[0]["reason"].as_str().unwrap().starts_with("pinned style 'mine': reference 1 of 3"));
    assert!(s[0]["path"].as_str().unwrap().starts_with("references/idea_spirit/pinned_"));
    // a pinned style also supplies its text
    assert!(plan.prompt.text.contains("Painted gouache."));
    assert!(plan.warnings.iter().any(|w| w.contains("pinned style 'mine'")));
    // the measured paragraph comes from the pinned images
    assert!(r["style_paragraph"].as_str().unwrap().contains("pinned reference images of the style 'mine'"));
    assert!(r["statistics"]["palette"][0]["name"].as_str().unwrap().contains("red"));
}

#[test]
fn a_copy_of_the_asset_skill_shelf_is_tier_two() {
    let game = fake_game(8);
    let h = harness_with_game(game.path());
    // the mod's own copy of the shelf: Chaos Redux calls the root gfx_references, the kit vanilla_reference
    for root in ["gfx_references", "vanilla_reference"] {
        let dir = format!(".claude/skills/some-skill/assets/{root}/icons/ideas");
        for i in 0..6 {
            write_png(
                h.root(),
                &format!("{dir}/shelf_{root}_{i}.png"),
                &spirit_icon([100 + i as u8 * 8, 100, 90], i % 2 == 0, i + if root == "gfx_references" { 0 } else { 20 }),
            );
        }
        // the contact sheet and other-sized pictures are not style images
        write_png(h.root(), &format!("{dir}/contact_sheet.png"), &Rgba::filled(60, 68, [1, 2, 3, 255]));
        write_png(h.root(), &format!("{dir}/odd_size.png"), &Rgba::filled(33, 33, [1, 2, 3, 255]));
    }
    let plan = plan_spirit(&h);
    let r = sources(&plan);
    assert_eq!(r["chosen_tier"], 2, "{r:#}");
    assert_eq!(r["tiers"][1]["found"], 12);
    for c in sent(&r) {
        assert!(c["reason"].as_str().unwrap().starts_with("mod asset folder copy: medoid "), "{c}");
        assert_eq!(c["origin"], "kit_shelf", "a shelf copy holds vanilla art and is recorded as such");
    }
    assert!(plan.references.iter().all(|x| x.origin == RefOrigin::KitShelf));
}

#[test]
fn with_nothing_in_the_mod_vanilla_is_used_and_needs_no_flag() {
    let game = fake_game(9);
    let h = harness_with_game(game.path());
    let plan = plan_spirit(&h);
    let r = sources(&plan);
    assert_eq!(r["chosen_tier"], 4, "{r:#}");
    assert_eq!(r["tiers"][2]["found"], 0);
    let s = sent(&r);
    assert!(!s.is_empty());
    for c in &s {
        assert_eq!(c["origin"], "installed_game");
        assert!(c["reason"].as_str().unwrap().starts_with("vanilla: medoid "), "{c}");
        assert!(c["reason"].as_str().unwrap().contains("of 9 idea_spirit images"), "{c}");
    }
    assert!(plan.references.iter().all(|x| x.origin == RefOrigin::InstalledGame));
    assert!(!plan.approvals.iter().any(|a| a.contains("Paradox") || a.contains("allow_vanilla")), "{:?}", plan.approvals);
    // the references go to the provider: generate sends them to the edits endpoint, no flag involved
    h.queue_edit(&synthetic_icon_png());
    let g = h.engine.generate(serde_json::from_value(json!({"plan_id": plan.plan_id, "idempotency_key": "k-vanilla"})).unwrap()).unwrap();
    assert!(g["candidates"][0]["candidate_id"].is_string(), "{g:#}");
    assert!(h.fixture.requests().iter().any(|r| r.url.contains("/v1/images/edits")), "references are sent through the edit call");
    // and the record keeps their origin
    let rec = h.engine.ledger.entries().unwrap().into_iter().find(|e| e.kind == "generated").unwrap();
    assert_eq!(rec.data["references"][0]["origin"], "installed_game");
    // nothing from the game was copied into the mod
    let mut stack = vec![h.root().to_path_buf()];
    while let Some(d) = stack.pop() {
        for e in std::fs::read_dir(d).unwrap().flatten() {
            let p = e.path();
            if p.is_dir() {
                stack.push(p);
            } else {
                assert!(!e.file_name().to_string_lossy().starts_with("idea_fake_"), "vanilla file copied into the mod: {}", p.display());
            }
        }
    }
}

#[test]
fn too_few_images_in_a_tier_fall_through_to_the_next() {
    let game = fake_game(8);
    let h = harness_with_game(game.path());
    mod_spirits(h.root(), "tiny", 2, [120, 120, 120], true);
    let r = sources(&plan_spirit(&h));
    assert_eq!(r["chosen_tier"], 4, "{r:#}");
    assert!(r["tiers"][2]["note"].as_str().unwrap().contains("only 2"));
    // and with no game and no mod images there is no automatic reference and no statistic
    let h2 = openai_harness();
    let plan = plan_spirit(&h2);
    let r = sources(&plan);
    assert_eq!(r["chosen_tier"], Value::Null);
    assert!(plan.references.is_empty() && r["statistics"].is_null() && r["style_paragraph"].is_null());
    assert!(!plan.prompt.text.contains("Style:"));
}

#[test]
fn the_same_images_give_the_same_choice_in_the_same_order() {
    let make = |feature: &str| {
        let h = openai_harness();
        // enough images that the choice is a real k-medoids, in two colour groups
        mod_spirits(h.root(), feature, 20, [110, 110, 110], true);
        for i in 0..20 {
            write_png(h.root(), &format!("gfx/interface/ideas/{feature}/idea_warm_{i:02}.png"), &spirit_icon([200, 90 + i as u8, 40], false, i + 5));
        }
        h
    };
    let a = make("alpha");
    let pa = plan_spirit(&a);
    let pa2 = plan_spirit(&a);
    assert_eq!(pa.plan_hash, pa2.plan_hash, "planning twice is the same plan");
    // the same files in a differently named folder: the choice depends on content, not on paths or listing order
    let b = make("zeta");
    let pb = plan_spirit(&b);
    let shas = |p: &imagegen_core::plan::Plan| p.references.iter().map(|r| r.sha256.clone()).collect::<Vec<_>>();
    assert_eq!(shas(&pa), shas(&pb));
    assert_eq!(shas(&pa).len(), 4);
    let stat_shas = |p: &imagegen_core::plan::Plan| {
        sources(p)["chosen"].as_array().unwrap().iter().map(|c| c["sha256"].as_str().unwrap().to_string()).collect::<Vec<_>>()
    };
    assert_eq!(stat_shas(&pa), stat_shas(&pb));
    // two colour groups: the four medoids are not all from one group
    let reds = pa.references.iter().filter(|r| r.path.contains("warm")).count();
    assert!(reds > 0 && reds < 4, "medoids should cover both groups, got {reds} warm of 4: {:?}", pa.references);
}

#[test]
fn statistics_and_the_prompt_follow_the_mods_palette() {
    let red = openai_harness();
    mod_spirits(red.root(), "reds", 10, [200, 25, 25], true);
    let grey = openai_harness();
    mod_spirits(grey.root(), "greys", 10, [115, 115, 115], false);
    let (pr, pg) = (plan_spirit(&red), plan_spirit(&grey));
    let (sr, sg) = (sources(&pr), sources(&pg));
    let (stat_r, stat_g) = (&sr["statistics"], &sg["statistics"]);
    assert!(stat_r["saturation"]["mean"].as_f64().unwrap() > 0.6, "{stat_r}");
    assert!(stat_g["saturation"]["mean"].as_f64().unwrap() < 0.05, "{stat_g}");
    assert!(stat_r["palette"][0]["name"].as_str().unwrap().contains("red"), "{stat_r}");
    assert!(stat_g["palette"][0]["name"].as_str().unwrap().contains("grey"), "{stat_g}");
    assert!(stat_r["outline_presence"].as_f64().unwrap() > 0.8 && stat_g["outline_presence"].as_f64().unwrap() < 0.1);
    for k in ["alpha_coverage", "edge_density", "margin_px", "subject_span"] {
        assert!(stat_r[k].is_number(), "{k}");
    }
    let (para_r, para_g) = (sr["style_paragraph"].as_str().unwrap(), sg["style_paragraph"].as_str().unwrap());
    assert!(para_r.contains("vivid") && para_r.contains("red") && para_r.contains("strong dark outline"), "{para_r}");
    assert!(para_g.contains("muted") && para_g.contains("grey") && para_g.contains("little or no dark outline"), "{para_g}");
    assert!(pr.prompt.text.contains(para_r) && pg.prompt.text.contains(para_g));
    assert_ne!(pr.prompt.sha256, pg.prompt.sha256);
}

/// Generate, process and validate a candidate made from `synthetic_icon_png` (orange-brown) for the focus family.
fn focus_candidate(h: &Harness, key: &str) -> String {
    // a mod with focus icons sends references, which goes through the edit call
    h.queue_edit(&synthetic_icon_png());
    let (_plan, _cand, processed) = h.make_processed("steel_gate", key);
    processed
}

/// `n` mod focus icons that look like the candidate: the pipeline's own processed output for the synthetic icon,
/// shifted in brightness a little per copy so the set has some spread.
fn mod_focus_like_candidate(h: &Harness, n: u32) {
    let (_p, _c, seed) = h.make_processed("seed_asset", "k-seed");
    let path = h
        .engine
        .ledger
        .entries()
        .unwrap()
        .into_iter()
        .find(|e| e.artifact_id.as_deref() == Some(seed.as_str()) && e.kind == "processed")
        .unwrap()
        .data["path"]
        .as_str()
        .unwrap()
        .to_string();
    let (base, _) = imagegen_core::pixels::decode(&h.read(&path), None, imagegen_core::pixels::DecodeLimits::default()).unwrap();
    assert_eq!((base.width, base.height), (100, 88));
    for i in 0..n {
        let mut img = base.clone();
        let d = (i as i32 - (n as i32) / 2) * 2;
        for px in img.data.chunks_exact_mut(4) {
            if px[3] > 0 {
                for c in &mut px[..3] {
                    *c = (i32::from(*c) + d).clamp(0, 255) as u8;
                }
            }
        }
        write_png(h.root(), &format!("gfx/interface/goals/mine/focus_like_{i:02}.png"), &img);
    }
}

fn grey_focus(root: &Path, n: u32) {
    for i in 0..n {
        let mut img = Rgba::new(100, 88);
        for y in 4..84u32 {
            for x in 4..96u32 {
                let v = 100 + ((x * 3 + y * 7 + i * 13) % 20) as u8;
                img.set_px(x, y, [v, v, v, 255]);
            }
        }
        write_png(root, &format!("gfx/interface/goals/mine/focus_grey_{i:02}.png"), &img);
    }
}

fn style_finding(v: &Value, code: &str) -> Option<Value> {
    v["results"][0]["findings"].as_array().unwrap().iter().find(|f| f["code"] == code).cloned()
}

#[test]
fn style_drift_warns_for_an_off_style_candidate_and_never_blocks() {
    // on-style: the mod's focus icons look like the candidate
    let on = openai_harness();
    mod_focus_like_candidate(&on, 10);
    let id = focus_candidate(&on, "k-on");
    let v = on.validate(&id);
    assert_eq!(v["status"], "pass", "{v:#}");
    assert!(style_finding(&v, "GFX-STYLE-DRIFT").is_none(), "{:#}", v["results"][0]["findings"]);
    let m = style_finding(&v, "GFX-STYLE-MATCH").expect("the numbers are recorded even without drift");
    assert!(m["evidence"]["z_rms"].as_f64().unwrap() <= m["evidence"]["threshold"].as_f64().unwrap());
    assert_eq!(v["results"][0]["style"]["verdict"], "GFX-STYLE-MATCH");

    // off-style: the mod's focus icons are flat grey, the candidate is saturated orange-brown
    let off = openai_harness();
    grey_focus(off.root(), 10);
    let id = focus_candidate(&off, "k-off");
    let v = off.validate(&id);
    assert_eq!(v["status"], "pass", "a style warning never fails a validation: {v:#}");
    let f = style_finding(&v, "GFX-STYLE-DRIFT").unwrap_or_else(|| panic!("{:#}", v["results"][0]["findings"]));
    assert_eq!(f["level"], "warning");
    assert!(f["evidence"]["z_rms"].as_f64().unwrap() > f["evidence"]["threshold"].as_f64().unwrap());
    assert_eq!(f["evidence"]["tier"], 3);
    assert!(!f["evidence"]["furthest_dimensions"].as_array().unwrap().is_empty());
    assert!(v["results"][0]["warnings"].as_u64().unwrap() >= 1);
    // the recorded validation carries the finding, the gate still opens, and the install goes through
    let entries = off.engine.ledger.entries().unwrap();
    let rec = entries.iter().rev().find(|e| e.kind == "validated").unwrap();
    assert!(rec.data["findings"].as_array().unwrap().iter().any(|f| f["code"] == "GFX-STYLE-DRIFT"));
    off.preview(&id);
    let approval = off.approve(&id, "icon_v1")["approval_id"].as_str().unwrap().to_string();
    off.install(&id, &approval, json!({})).expect("a style warning must never block an install");
    assert!(off.exists("gfx/interface/goals/f/focus_steel_gate.dds") || off.exists("gfx/interface/goals/iron_pact/focus_steel_gate.dds"));
}

#[test]
fn the_style_check_is_part_of_every_family_check_set() {
    let h = openai_harness();
    let all = h.engine.families_info(serde_json::from_value(json!({})).unwrap()).unwrap();
    for fam in all["families"].as_array().unwrap() {
        let one = h.engine.families_info(serde_json::from_value(json!({"family": fam["family"]})).unwrap()).unwrap();
        let checks = one["family"]["checks"].as_array().unwrap();
        assert!(checks.iter().any(|c| c == "style"), "{} lacks the style check", fam["family"]);
    }
    // without any source the check reports that it had nothing to compare with, and does not fail
    let id = focus_candidate(&h, "k-none");
    let v = h.validate(&id);
    assert_eq!(v["status"], "pass");
    assert_eq!(v["results"][0]["style"]["available"], false);
    assert!(style_finding(&v, "GFX-STYLE-DRIFT").is_none() && style_finding(&v, "GFX-STYLE-MATCH").is_none());
}

